/* Isolated design prototype. Fictional records; no Electron API or owner database. */
const K = window.KnowledgeEditor;
const icon = name => K.icon(name);
const escape = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options = {A:['Classic workspace','A folder tree beside an open page.'],B:['Folder table','Folders and a compact note table.'],C:['Compact navigator','An icon rail and focused folder navigator.'],D:['Tabbed notebook','A page tree with open-note tabs.'],E:['Visual library','A folder library with quiet note previews.']};
const storeKey = 'tempo-knowledge-design-demo-v1';
let saved; try { saved = JSON.parse(localStorage.getItem(storeKey) || '{}'); } catch { saved = {}; }
const state = { option: new URLSearchParams(location.search).get('option') || saved.option || 'A', route: 'Notes', theme: saved.theme || 'light', collapsed:false, space:'Work', note:'pipelines', prefs:{wide:false,serif:false,thought:true,...saved.prefs}, edits:saved.edits||{}, covers:saved.covers||{}, tasks:saved.tasks||[
  {id:1,title:'Validate source data',project:'Warehouse migration',area:'Work',status:'Today',time:'09:00',priority:'High'},
  {id:2,title:'Document the ingestion flow',project:'Warehouse migration',area:'Work',status:'Today',time:'11:30',priority:'Normal'},
  {id:3,title:'Practise Python return values',project:'Software engineering',area:'Learning',status:'Today',time:'18:00',priority:'Normal'},
  {id:4,title:'Read about incremental models',project:'Warehouse migration',area:'Work',status:'Later',time:'',priority:'Normal'},
  {id:5,title:'Build a small SQL test fixture',project:'Engineering notes',area:'Learning',status:'Later',time:'',priority:'Normal'},
  {id:6,title:'Map the source tables',project:'Warehouse migration',area:'Work',status:'Done',time:'',priority:'Normal'}
], habits:saved.habits||[false,true,false,false], taskFilter:'', selectedGraph:'pipelines', choice:saved.choice||null, library:true, folders:saved.folders||{'Engineering':true,'Learning':true,'Personal':false}, navOrder:saved.navOrder||[], graphOpen:false, graphTypes:['note','topic','project','curriculum'], graphSelection:'note:pipelines', reflection:saved.reflection||'', activeFolder:'' };
if (!options[state.option]) state.option='A';
const notes = {
  pipelines:{title:'Reliable data pipelines',folder:'Engineering',tag:'data engineering',updated:'Yesterday',content:'<p>A pipeline is a series of small promises: collect the right data, transform it deliberately, and make the result dependable.</p><h2>Design for failure</h2><p>Before adding another step, define what success means and how a failed run should recover.</p><ul><li>Every run has an identity.</li><li>Repeated runs should produce the same result.</li><li>Validation happens before the data becomes available.</li></ul><h2>A simple validation boundary</h2><pre><code>def validate_batch(rows):\n    if not rows:\n        raise ValueError("The batch is empty")\n    return all(row["id"] is not None for row in rows)</code></pre><p>The next piece to explore is <a href="#note/sql">SQL joins and cardinality</a>.</p>',links:['sql','python','warehouse']},
  sql:{title:'SQL joins and cardinality',folder:'Engineering',tag:'SQL',updated:'Tuesday',content:'<p>Before joining two tables, ask what one row means in each table.</p><h2>Predict the number of rows</h2><p>A join can multiply rows when the key is not unique. Start by checking the relationship: one-to-one, one-to-many or many-to-many.</p><pre><code>SELECT customer_id, COUNT(*)\nFROM orders\nGROUP BY customer_id;</code></pre><h2>Questions to keep close</h2><ul><li>Which table defines the grain of the result?</li><li>What happens when a matching row is missing?</li><li>Can either join key appear more than once?</li></ul><p>These checks belong at the validation boundary in <a href="#note/pipelines">Reliable data pipelines</a>.</p>',links:['pipelines','warehouse']},
  python:{title:'Functions and return values',folder:'Learning',tag:'Python',updated:'Yesterday',content:'<p>A function takes inputs, does a piece of work, and can return a value to its caller.</p><h2>Return versus print</h2><p><strong>Return</strong> gives a value back to the calling code. <strong>Print</strong> displays text. They do different jobs.</p><pre><code>def double(value):\n    return value * 2\n\nresult = double(6)\nassert result == 12</code></pre><h2>Try it</h2><ul><li>Write a function that returns the larger of two values.</li><li>Predict what a function returns when it has no return statement.</li></ul>',links:['pipelines']},
  stoic:{title:'What is within my control?',folder:'Personal',tag:'reflection',updated:'Monday',content:'<p>Today I want to distinguish what I can influence from what I can only respond to.</p><h2>What I can choose</h2><ul><li>The care I put into my work.</li><li>How I respond when a plan changes.</li><li>Whether I make room to learn.</li></ul><p>I do not need a perfect day to make a deliberate choice.</p>',links:[]}
};
Object.assign(notes,saved.notes||{});
notes.math ||= {title:'Irrational numbers',folder:'Learning',tag:'Mathematics',updated:'Yesterday',content:'<p>Some numbers cannot be expressed as a ratio of whole numbers.</p><h2>A square with area two</h2><p>The side length of a square with area two is √2. It is a length, before it is a symbol.</p>',links:[]};
const notePaths={pipelines:'Engineering/Data systems',sql:'Engineering/Queries',python:'Learning/Python',math:'Learning/Mathematics',stoic:'Personal/Reflections'};
Object.entries(notes).forEach(([id,n])=>{n.path ||= notePaths[id] || n.folder; n.markdown ||= K.markdown(n.content);});
const projects = saved.projects || [{id:'warehouse',title:'Warehouse migration',status:'In progress',progress:42,next:'Validate source data',date:'Oct 20'},{id:'reporting',title:'Reporting foundations',status:'Planned',progress:16,next:'Define the metric grain',date:'Oct 28'}];
const nav = [['Home','House'],['Plan','CalendarDays'],['Habits','CircleCheck'],['Tasks','Columns3'],['Work','BriefcaseBusiness'],['Focus','Timer'],['Study','BookOpen'],['Notes','Files'],['Statistics','ChartNoAxesCombined'],['Goals','Target'],['Journal','NotebookPen']];
function persist(){try{localStorage.setItem(storeKey,JSON.stringify({option:state.option,theme:state.theme,prefs:state.prefs,edits:state.edits,covers:state.covers,tasks:state.tasks,habits:state.habits,choice:state.choice,emptyFolders:saved.emptyFolders||[],notes,projects,navOrder:state.navOrder,folders:state.folders,reflection:state.reflection}));}catch{toast('Preview storage is full. Remove a cover and try again.');}}
let toastTimer;function toast(message){const el=document.querySelector('#notice');el.textContent=message;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),2600);}
function logo(){return '<svg class="logo" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" aria-hidden="true"><path d="M3 9v6M7.5 5v14M12 2v20M16.5 6v12M21 10v4"/></svg>';}
const actionLabels={theme:'Toggle theme',collapse:'Toggle sidebar',search:'Search Tempo',wide:'Toggle page width',serif:'Toggle writing font','page-menu':'Page options','reset-timer':'Reset timer','new-note':'New note',graph:'Toggle graph panel','graph-expand':'Expand graph panel','graph-in':'Zoom in','graph-out':'Zoom out','graph-fit':'Fit graph','previous-day':'Previous day','next-day':'Next day','previous-week':'Previous week','next-week':'Next week'};
const button=(text,action,cls='')=>'<button class="'+cls+'" data-action="'+action+'" aria-label="'+escape(text.replace(/<svg[\s\S]*?<\/svg>/g,'').replace(/<[^>]*>/g,'').trim()||actionLabels[action]|| (action.startsWith('focus-')?'Focus on task':'More options'))+'">'+text+'</button>';
const routeButton=(text,route,cls='')=>`<button class="${cls}" data-route="${route}" aria-label="${escape(text.replace(/<svg[\s\S]*?<\/svg>/g,'').replace(/<[^>]*>/g,'').trim()||route)}">${text}</button>`;
function studio(){document.querySelector('#studio').innerHTML=`<div class="studio-info"><strong>Tempo · Workspace options</strong><small>Working preview · fictional data</small></div><div class="options" role="group" aria-label="Choose a design option">${Object.entries(options).map(([key,[name]])=>`<button data-option="${key}" aria-pressed="${key===state.option}">${key} · ${name}</button>`).join('')}</div><div class="row choice">${button(icon(state.theme==='light'?'Moon':'Sun'),'theme','icon-button')}<button class="primary" data-action="choose">${state.choice===state.option?'Selected '+state.option:'Choose '+state.option}</button></div>`;}
function orderedNav(){const order=state.navOrder.filter(name=>nav.some(([n])=>n===name));return [...order,...nav.map(([name])=>name).filter(name=>!order.includes(name))].map(name=>nav.find(([n])=>n===name));}
function tree(filter='',base=''){const query=filter.toLowerCase();const matching=Object.entries(notes).filter(([,n])=>n.title.toLowerCase().includes(query)||n.path.toLowerCase().includes(query));function level(path){const children=[...new Set([...matching.filter(([,n])=>n.path===path||n.path.startsWith(path?path+'/':'')).map(([,n])=>n.path.slice(path?path.length+1:0).split('/')[0]).filter(Boolean),...(saved.emptyFolders||[]).filter(p=>p.startsWith(path?path+'/':'')).map(p=>p.slice(path?path.length+1:0).split('/')[0]).filter(Boolean)])];return children.map(name=>{const full=path?path+'/'+name:name;const open=query||state.folders[full];const local=matching.filter(([,n])=>n.path===full);return '<div class="tree-branch"><button class="tree-folder" data-folder="'+escape(full)+'" aria-expanded="'+!!open+'">'+icon(open?'ChevronDown':'ChevronRight')+icon(open?'FolderOpen':'Folder')+'<span>'+escape(name)+'</span></button>'+(open?'<div class="tree-children">'+level(full)+local.map(([id,n])=>'<button class="tree-note '+(!state.library&&state.note===id?'active':'')+'" data-note="'+id+'">'+icon('FileText')+'<span>'+escape(n.title)+'</span></button>').join('')+'</div>':'')+'</div>';}).join('');}return '<div class="folder-tree" aria-label="Note folders">'+level(base)+'</div>';}
function sidebar(){return '<aside class="sidebar" aria-label="Workspace navigation"><div class="brand">'+logo()+'<span>Tempo</span><div class="spacer"></div>'+button(icon('PanelLeftClose'),'collapse','collapse icon-button')+'</div><button class="search-field" data-action="search" aria-label="Search Tempo">'+icon('Search')+'<span class="nav-text">Search</span><kbd>Ctrl K</kbd></button><nav aria-label="Main pages">'+orderedNav().map(([name,image])=>'<button class="nav-item '+(state.route===name?'active':'')+'" data-route="'+name+'" title="'+name+'" '+(state.route===name?'aria-current="page"':'')+'>'+icon(image)+'<span class="nav-text">'+name+'</span></button>').join('')+'</nav><div class="nav-group '+(state.route==='Notes'&&!state.graphOpen?'notes-tree-duplicate':'')+'"><div class="nav-title">Pages '+button(icon('Plus'),'new-note','icon-button')+'</div>'+tree()+'</div><div class="sidebar-bottom">'+button(icon('ListFilter')+'<span class="nav-text">Arrange sidebar</span>','arrange','nav-item')+routeButton(icon('Settings')+'<span class="nav-text">Settings</span>','Settings','nav-item')+'<div class="profile"><span class="avatar">D</span><div>Divine’s workspace<div class="muted small">Local preview</div></div></div></div></aside>';}
function spacePanel(){return '<aside class="space-panel"><h3>Folders</h3>'+tree()+'</aside>';}
function head(title,action=''){return `<div class="page-head"><div><h1>${title}</h1></div><div class="spacer"></div>${action}</div>`;}
function topbar(){const label=state.route==='Notes'&&!state.library?notes[state.note].title:state.route;return '<header class="topbar">'+button(icon('PanelLeft'),'collapse','icon-button')+'<div class="breadcrumb"><span class="bread-root muted">Tempo</span><span class="muted bread-root">/</span><span>'+escape(label)+'</span></div><div class="actions"><span class="saved muted" id="save-status">'+(state.route==='Journal'||state.route==='Notes'&&!state.library?'Saved in preview':'')+'</span>'+button(icon('Search'),'search','icon-button')+button(icon('Waypoints'),'graph','icon-button graph-toggle')+button(icon('MoreHorizontal'),'page-menu','icon-button')+'</div></header>';}
function tabs(){return `<div class="tabs-bar">${[['Home','House'],['Notes','FileText'],['Tasks','Columns3'],['Work','BriefcaseBusiness']].map(([label,img])=>routeButton(icon(img)+label,label,state.route===label?'active':'')).join('')}</div>`;}
function taskRows(tasks){return tasks.map(task=>`<div class="task-row ${task.status==='Done'?'done':''}"><button class="check ${task.status==='Done'?'done':''}" data-check="${task.id}" aria-label="${task.status==='Done'?'Reopen':'Complete'} ${escape(task.title)}">${task.status==='Done'?icon('Check'):''}</button><div class="content"><div class="task-name">${escape(task.title)}</div><div class="small muted">${escape(task.project)}</div></div><span class="task-time">${task.time}</span>${button(icon('Play'),'focus-'+task.id,'icon-button quiet')}</div>`).join('');}
function addTask(status='Today'){return `<form class="inline-add" data-add-task="${status}">${icon('Plus')}<input aria-label="New ${status.toLowerCase()} task" placeholder="Add a task…" required maxlength="180"><button type="submit">Add</button></form>`;}
function taskSection(title='Today',area=''){return `<section><div class="section-title"><h2>${title}</h2>${routeButton('Open plan '+icon('ArrowUpRight'),'Plan','small quiet')}</div>${taskRows(state.tasks.filter(t=>t.status==='Today'&&(!area||t.area===area)))}${addTask()}</section>`;}
function continueStudy(){return `<section><div class="section-title"><h2>Continue studying</h2>${routeButton(icon('ArrowUpRight'),'Study','icon-button quiet')}</div>${[['Functions and return values','Software engineering · 12 / 984 topics','python',2],['Irrational numbers','Mathematics · 6 / 483 topics','math',1]].map(([title,meta,id,p])=>`<button class="link-row" data-note="${id}">${icon('BookOpen')}<div>${title}<div class="small muted">${meta}</div><span class="progress" style="--progress:${p}%"><i></i></span></div>${icon('ArrowUpRight')}</button>`).join('')}</section>`;}
function recentNotes(){return `<section class="section"><div class="section-title"><h2>Recently opened</h2>${routeButton('All notes','Notes','small quiet')}</div>${['pipelines','sql'].map(id=>`<button class="link-row" data-note="${id}">${icon('FileText')}<div>${notes[id].title}<div class="small muted">${notes[id].folder} · ${notes[id].updated}</div></div>${icon('ArrowUpRight')}</button>`).join('')}</section>`;}
function thought(){return state.prefs.thought?'<div class="thought reading"><blockquote>“Make the best use of what is in your power, and take the rest as it happens.”</blockquote><cite>Epictetus · Enchiridion, 1</cite></div>':'';}
function habitSnippet(){return `<section class="section"><div class="section-title"><h2>Habits</h2>${routeButton('All habits','Habits','small quiet')}</div>${['Read for 25 minutes','Meditate'].map((name,i)=>`<div class="task-row"><button class="check ${state.habits[i]?'done':''}" data-habit="${i}" aria-label="Check in ${name}">${state.habits[i]?icon('Check'):''}</button><div>${name}</div></div>`).join('')}</section>`;}
function home(){return '<div class="main incumbent-home"><div class="section-title"><span class="muted">Thursday, October 8</span>'+routeButton(icon('Timer')+' Start focusing','Focus','quiet')+'</div><div class="incumbent-thought"><blockquote>Practise steadiness with<br>small inconveniences before<br>the larger ones arrive.</blockquote><cite>Inspired by Epictetus · Enchiridion, XII</cite>'+routeButton('Reflect on this tonight '+icon('ArrowRight'),'Journal','quiet')+'</div><div class="home-boundary">Home is retained from your installed app. This preview changes Notes and navigation only.</div>'+continueStudy()+'</div>';}
function library(){const items=Object.entries(notes).filter(([,n])=>!state.activeFolder||n.path===state.activeFolder||n.path.startsWith(state.activeFolder+'/'));const folders=[...new Set(Object.values(notes).map(n=>n.folder))];const cards=items.map(([id,n])=>'<button class="library-note" data-note="'+id+'">'+icon('FileText')+'<div><strong>'+escape(n.title)+'</strong><span>'+escape(n.path)+'</span>'+(state.option==='E'?'<p>'+escape(K.markdown(state.edits[id]||n.content).replace(/[#*\x60\[\]]/g,'').slice(0,120))+'</p>':'')+'</div><span class="library-updated">'+n.updated+'</span>'+icon('ChevronRight')+'</button>').join('');return '<div class="notes-library main option-'+state.option+'">'+head('Notes',button(icon('Plus')+' New note','new-note','quiet'))+'<div class="library-toolbar"><div class="search-field">'+icon('Search')+'<input id="library-filter" aria-label="Find a note" placeholder="Find a note…"></div>'+button(icon('FolderPlus')+' New folder','new-folder','quiet')+'</div><div class="library-layout"><aside class="library-folders"><div class="section-title"><h3>Folders</h3>'+button('All','all-folders','quiet small')+'</div>'+tree()+'</aside><section class="library-content"><div class="folder-tiles">'+folders.map(folder=>'<button data-library-folder="'+folder+'" aria-pressed="'+(state.activeFolder===folder)+'">'+icon('Folder')+'<span>'+folder+'</span><small>'+Object.values(notes).filter(n=>n.folder===folder).length+'</small></button>').join('')+'</div><div class="library-list-head"><span>'+escape(state.activeFolder||'All notes')+'</span><span>'+items.length+'</span></div><div id="library-list">'+cards+'</div></section></div></div>';}
function noteView(journal=false){const id=journal?'journal':state.note;const note=journal?{title:'Thursday, October 8',folder:'Journal',tag:'daily page',content:'<p>A new day, a little room to think.</p><h2>Today</h2><p>I want to make steady progress on the migration, leave clear notes for future me, and keep a little energy for learning.</p><h2>One thing to remember</h2><p>I can choose the care I put into the next small step.</p>',links:['stoic']}:notes[id];return `<div class="split-notes ${state.prefs.wide?'wide':''} ${state.prefs.serif?'serif':''}">${!journal?`<aside class="note-index">${button(icon('ArrowLeft')+' All notes','all-notes','quiet small')}<h3>Folders</h3><div class="search-field">${icon('Search')}<input id="note-filter" placeholder="Filter notes…" aria-label="Filter notes"></div><div id="note-list">${tree()}</div>${button(icon('Plus')+' New note','new-note','quiet small')}</aside>`:''}<div class="note-canvas"><article class="document">${state.covers[id]?`<div class="cover" style="background-image:url('${state.covers[id]}')">${button(icon('Image')+' Change','cover','small')}</div>`:''}<div class="document-actions"><span>${!journal?button(icon('FolderTree')+' Browse notes','note-drawer','mobile-browse'):''}${!state.covers[id]?button(icon('ImagePlus')+' Add cover','cover'):''}</span>${button(icon('Type'),'serif','icon-button')}</div><div class="page-icon">${icon(journal?'NotebookPen':'FileText')}</div>${head(escape(note.title))}<div class="note-meta"><span>${note.folder}</span><span class="tag">${note.tag}</span><span id="word-count"></span><div class="spacer"></div><span>Private</span></div><div id="editor"></div><section class="related"><h3>Linked pages</h3>${note.links.map(link=>link==='warehouse'?routeButton(icon('BriefcaseBusiness')+' Warehouse migration','Work'):`<button data-note="${link}">${icon('FileText')} ${notes[link].title}</button>`).join('')||'<span class="small muted">No linked pages yet</span>'}</section></article></div></div>`;}
function noteList(filter=''){return Object.entries(notes).filter(([,n])=>n.title.toLowerCase().includes(filter.toLowerCase())).map(([id,n])=>`<button class="note-entry ${state.note===id?'active':''}" data-note="${id}">${escape(n.title)}<span>${n.folder} · ${n.updated}</span></button>`).join('')||'<p class="no-results small">No matching notes</p>';}
function taskBoard(){return `<div class="main">${head('Tasks',button(icon('Plus')+' New task','new-task','quiet'))}<div class="board-top"><div class="search-field">${icon('Search')}<input id="task-filter" aria-label="Search tasks" placeholder="Search tasks…" value="${escape(state.taskFilter)}"></div><span class="spacer"></span><span class="small muted">${state.tasks.length} tasks</span></div><div class="board" id="board">${boardColumns()}</div></div>`;}
function boardColumns(){return ['Later','Today','Done'].map(status=>`<section class="column" data-drop="${status}" aria-label="${status} tasks"><div class="column-title"><i class="dot"></i>${status}<span class="count">${state.tasks.filter(t=>t.status===status).length}</span></div>${state.tasks.filter(t=>t.status===status&&t.title.toLowerCase().includes(state.taskFilter.toLowerCase())).map(t=>`<article class="task-card" draggable="true" data-drag="${t.id}"><div>${escape(t.title)}</div><p class="small">${escape(t.project)}</p><footer>${t.priority==='High'?'<span class="tag">High</span>':'<span class="small muted">'+t.area+'</span>'}<select data-move="${t.id}" aria-label="Move ${escape(t.title)}">${['Later','Today','Done'].map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select></footer></article>`).join('')}${addTask(status)}</section>`).join('');}
function plan(){return `<div class="main" style="max-width:970px">${head('Today',button(icon('ChevronLeft'),'previous-day','icon-button')+'<span class="small muted" style="padding-top:8px">Oct 8</span>'+button(icon('ChevronRight'),'next-day','icon-button'))}${taskSection('Focus queue')}<div class="section"><div class="section-title"><h2>Available next</h2>${routeButton('Open board '+icon('ArrowUpRight'),'Tasks','quiet small')}</div>${state.tasks.filter(t=>t.status==='Later').map(t=>`<div class="task-row"><div class="content">${escape(t.title)}<div class="small muted">${t.project}</div></div><button data-schedule="${t.id}" class="small quiet">${icon('Plus')} Today</button></div>`).join('')}</div></div>`;}
function work(){return `<div class="main">${head('Work',button(icon('Plus')+' New project','new-project','quiet'))}<table class="table"><thead><tr><th>Project</th><th>Status</th><th>Progress</th><th>Next action</th></tr></thead><tbody>${projects.map(p=>`<tr><td><button data-project="${p.id}">${icon('FolderKanban')} ${p.title}</button></td><td><span class="tag">${p.status}</span></td><td style="min-width:90px"><span class="small muted">${p.progress}%</span><span class="progress" style="--progress:${p.progress}%"><i></i></span></td><td>${escape(p.next)}</td></tr>`).join('')}</tbody></table><div class="section">${taskSection('Work queue','Work')}</div></div>`;}
let focusMinutes=25,focusSeconds=1500,focusRunning=false,focusInterval,focusTitle='Validate source data';
function focus(){return `<div class="main">${head('Focus')}<div class="focus-layout"><section class="focus-center"><p class="muted" id="focus-title">${escape(focusTitle)}</p><div class="timer" id="timer">${timerText()}</div><div class="row" style="justify-content:center">${button(icon(focusRunning?'Pause':'Play')+(focusRunning?'Pause':'Start'),'timer','primary')}${button(icon('RotateCcw'),'reset-timer','icon-button')}</div><div class="focus-controls" role="group" aria-label="Focus presets">${[15,25,50].map(m=>`<button data-preset="${m}" aria-pressed="${m===focusMinutes}">${m} min</button>`).join('')}<span class="muted">·</span>${button('Pomodoro','pomodoro','small')}${button('Track time','track','small')}</div></section><section><div class="section-title"><h2>Queue</h2>${routeButton('Plan','Plan','small quiet')}</div>${taskRows(state.tasks.filter(t=>t.status==='Today'))}</section></div></div>`;}
function timerText(){return `${Math.floor(focusSeconds/60).toString().padStart(2,'0')}:${(focusSeconds%60).toString().padStart(2,'0')}`;}
function habits(){return `<div class="main" style="max-width:1050px">${head('Habits',button(icon('Plus')+' New habit','new-habit','quiet'))}<div class="section-title"><span class="small muted">Thursday, October 8</span><div class="row">${button('Today','habits-today','small')}${button('History','habits-history','small')}${button('Recovery','recovery','small')}</div></div>${['Read for 25 minutes','Meditate','Practise one problem','Take a walk'].map((name,i)=>`<div class="habit-row"><button class="check ${state.habits[i]?'done':''}" data-habit="${i}" aria-label="Check in ${name}">${state.habits[i]?icon('Check'):''}</button><div class="content">${name}<div class="habit-dots" aria-label="Six recent completions, one open day">${'<i></i>'.repeat(7)}</div></div><span class="habit-streak">${icon('Flame')} ${[8,12,4,6][i]}</span>${button(icon('MoreHorizontal'),'habit-menu-'+i,'icon-button quiet')}</div>`).join('')}</div>`;}
function chart(){return `<svg class="report-chart" viewBox="0 0 900 250" role="img" aria-label="Illustrative daily focus minutes: 45, 90, 65, 120, 80, 30, 55">${[40,100,160,220].map((y,i)=>`<line x1="42" y1="${y}" x2="870" y2="${y}"/><text x="3" y="${y+4}">${120-i*40}</text>`).join('')}<polyline points="45,153 182,85 319,123 456,40 593,100 730,175 867,138"/>${[[45,153],[182,85],[319,123],[456,40],[593,100],[730,175],[867,138]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="4"/><text x="${x-10}" y="246">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</text>`).join('')}</svg>`;}
function report(title='Statistics'){return `<div class="main">${head(title)}<div class="section-title"><div class="row">${button(icon('ChevronLeft'),'previous-week','icon-button')}<strong>October 5 – 11</strong>${button(icon('ChevronRight'),'next-week','icon-button')}</div><span class="small muted">Focus minutes · preview data</span></div>${chart()}<div class="report-stats"><div><strong>8 h 5 m</strong><span class="small muted">Focused</span></div><div><strong>12</strong><span class="small muted">Tasks completed</span></div><div><strong>7</strong><span class="small muted">Topics learned</span></div><div><strong>24</strong><span class="small muted">Habit check-ins</span></div></div></div>`;}
function study(){return `<div class="main">${head('Study',button(icon('Import')+' Import','import-roadmap','quiet')+button(icon('Plus')+' New curriculum','curriculum','quiet'))}<div class="section-title"><h2>Current focus</h2></div>${[['Software engineering',12,984,'4 h 25 m','Functions and return values','python'],['Mathematics',6,483,'1 h 40 m','Irrational numbers','math']].map(([title,num,total,time,current,id])=>`<button class="link-row" data-note="${id}" style="padding:24px 0">${icon('BookOpen')}<div><h2>${title}</h2><div class="small muted">${num} / ${total} topics · ${time}</div><div class="small muted">Continue · ${current}</div></div><div><span class="small muted">${Math.round(num/total*100)}%</span><span class="progress" style="--progress:${num/total*100}%"><i></i></span></div>${icon('ChevronRight')}</button>`).join('')}<div class="section-title section"><h2>Library</h2></div><button class="link-row" data-action="finance">${icon('BookOpen')}<div><h2>Economics & markets</h2><div class="small muted">1 / 356 topics · 0 m</div><div class="small muted">Continue · Utility functions</div></div><span class="progress" style="--progress:1%"><i></i></span>${icon('ChevronRight')}</button></div>`;}
function goals(){return `<div class="main">${head('Goals',button(icon('Plus')+' New goal','goal','quiet'))}${[['Build reliable foundations','Warehouse migration · Oct 20',42],['Finish Python fundamentals','Software engineering · Oct 31',27],['Read with consistency','Reading habit · This month',65]].map(([title,meta,p])=>`<section class="goal-row"><div><h2>${title}</h2><p class="small muted">${meta}</p></div><div class="row"><span class="progress" style="--progress:${p}%"><i></i></span><span class="small muted">${p}%</span></div></section>`).join('')}</div>`;}
function prefs(){const pref=(label,control,detail='')=>`<div class="pref-row"><div>${label}${detail?'<p>'+detail+'</p>':''}</div>${control}</div>`;const toggle=(name)=>`<button class="toggle" data-pref="${name}" aria-label="${name==='wide'?'Wide pages':name==='serif'?'Serif writing font':'Daily thought'}" aria-pressed="${state.prefs[name]}"><i></i></button>`;return `<div class="main prefs">${head('Settings')}<div class="${state.option==='D'?'settings-two':''}"><nav class="pref-nav" aria-label="Settings sections">${['Appearance','Writing','Data'].map(name=>`<button data-pref-section="${name.toLowerCase()}">${name}</button>`).join('')}</nav><div><section class="pref-group" id="appearance"><h2>Appearance</h2>${pref('Theme',`<select id="theme-select" aria-label="Theme"><option value="light" ${state.theme==='light'?'selected':''}>Light</option><option value="dark" ${state.theme==='dark'?'selected':''}>Dark</option></select>`)}${pref('Accent','<span class="tag">Petrol</span>')}${pref('Sidebar order',button('Arrange','arrange','quiet small'))}</section><section class="pref-group" id="writing"><h2>Writing</h2>${pref('Wide pages',toggle('wide'))}${pref('Serif writing font',toggle('serif'))}${pref('Default notebook','<span class="muted small">Engineering</span>')}</section><section class="pref-group" id="data"><h2>Data</h2>${pref('Storage','<span class="muted small">Local preview only</span>')}${pref('Export this design choice',button(icon('Download')+' Export','export','border small'))}${pref('Preview data',button('Reset preview','reset','small quiet'),'Only fictional records are used here.')}</section></div></div></div>`;}
function graphRecords(){
 const records=[],edges=[];const add=(id,title,type,extra={})=>records.push({id,title,type,...extra});const edge=(source,target,relation)=>edges.push({source,target,relation});
 Object.entries(notes).forEach(([id,n])=>add('note:'+id,n.title,'note',{noteId:id,path:n.path}));
 projects.forEach(p=>add('project:'+p.id,p.title,'project',{projectId:p.id}));
 const curricula=[['swe','Software engineering',['How computers work','Python values','Control flow','Functions','Return values','Modules','Exceptions','Testing','Data structures','Algorithms','Memory','Git','SQL','HTTP','Concurrency','Linux','APIs','Debugging','Transactions','Indexes','Data models','Batch processing','Streaming','Observability','CI pipelines','Containers','Deployment','Reliability','Design boundaries','Documentation']],['math','Mathematics',['Quantity','Units','Whole numbers','Fractions','Decimals','Ratios','Proportions','Percentages','Powers','Square roots','Irrational numbers','Number line','Equations','Inequalities','Coordinates','Functions','Slope','Lines','Quadratics','Polynomials','Sequences','Limits','Derivatives','Integrals','Vectors','Matrices','Probability','Random variables','Distributions','Statistics']],['data','Data engineering',['Source systems','Table grain','Data contracts','Extraction','Schema changes','Watermarks','Ingestion','Idempotency','Partitions','Orchestration','Backfills','Validation','Null handling','Deduplication','Join cardinality','SQL models','Incremental models','Warehouse layers','Fact tables','Dimension tables','Slowly changing dimensions','Lineage','Data quality','Freshness','Metric definitions','Access control','Cost management','Pipeline monitoring','Incident recovery','Runbooks']]];
 curricula.forEach(([key,title,topics])=>{add('curriculum:'+key,title,'curriculum');topics.forEach((name,i)=>{const id='topic:'+key+':'+i;add(id,name,'topic',{curriculumId:key});edge(id,'curriculum:'+key,'belongs to');if(i)edge(id,'topic:'+key+':'+(i-1),'follows');});});
 Object.entries(notes).forEach(([id,n])=>{const found=[...new Set([...n.links,...(K.markdown(state.edits[id]||n.content).match(/#note\/[a-z0-9-]+/g)||[]).map(link=>link.slice(6))])];found.forEach(link=>{const target=notes[link]?'note:'+link:projects.some(p=>p.id===link)?'project:'+link:null;if(target)edge('note:'+id,target,'links to');});});
 [['pipelines','data',6],['sql','data',14],['python','swe',4],['math','math',10]].forEach(([id,c,i])=>edge('note:'+id,'topic:'+c+':'+i,'explains'));
 edge('project:warehouse','curriculum:data','uses');edge('project:reporting','topic:data:24','uses');edge('topic:swe:12','topic:data:15','related to');
 const visible=records.filter(r=>state.graphTypes.includes(r.type));const ids=new Set(visible.map(r=>r.id));return {records:visible,edges:edges.filter(e=>ids.has(e.source)&&ids.has(e.target))};
}
function inspectRecord(record){const data=graphRecords(),dialog=document.createElement('dialog');dialog.className='record-inspector';dialog.innerHTML='<div class="graph-head"><span class="small muted">'+escape(record.type)+' · '+escape(record.id)+'</span><button data-cancel aria-label="Close record">'+icon('X')+'</button></div><h2>'+escape(record.title)+'</h2>'+(record.type==='project'?'<p>'+escape(projects.find(p=>p.id===record.projectId)?.status||'')+'</p>'+taskRows(state.tasks.filter(t=>t.project===record.title)):'<p>Fictional study record · '+escape(record.curriculumId||record.title)+'</p>')+'<h3 class="section">Linked records</h3>'+data.edges.filter(e=>e.source===record.id||e.target===record.id).map(e=>{const other=data.records.find(r=>r.id===(e.source===record.id?e.target:e.source));return '<button class="link-row" data-graph-record="'+other.id+'">'+escape(other.title)+'<small class="muted">'+e.relation+'</small></button>';}).join('');document.body.append(dialog);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.addEventListener('click',e=>{if(e.target.closest('[data-graph-record],[data-action^=focus]'))dialog.close();});dialog.showModal();}
function graphPanel(){return '<aside class="right-graph" aria-label="Knowledge graph"><div class="graph-head"><h3>Graph</h3>'+button(icon('Maximize2'),'graph-expand','icon-button')+button(icon('PanelRightClose'),'graph','icon-button')+'</div><div class="graph-filters">'+[['note','Notes'],['topic','Topics'],['project','Projects'],['curriculum','Curricula']].map(([type,label])=>'<button data-graph-type="'+type+'" aria-pressed="'+state.graphTypes.includes(type)+'">'+label+'</button>').join('')+'</div><div class="graph-stage"><canvas id="record-graph" tabindex="0" aria-label="Record network. Drag to pan, scroll to zoom. Choose a record in the list below for keyboard access."></canvas><div class="graph-controls">'+button(icon('Minus'),'graph-out','icon-button')+button(icon('Plus'),'graph-in','icon-button')+button(icon('Scan'),'graph-fit','icon-button')+'</div></div><div class="graph-summary" id="graph-summary"></div><div class="graph-search search-field">'+icon('Search')+'<input id="graph-filter" aria-label="Find a graph record" placeholder="Find a record…"></div><div id="graph-records" class="graph-records"></div><div id="graph-detail" class="graph-detail"></div></aside>';}
function graphDetails(id){state.graphSelection=id;const data=graphRecords();const r=data.records.find(n=>n.id===id);if(!r)return;const linked=data.edges.filter(e=>e.source===id||e.target===id);document.querySelector('#graph-detail').innerHTML='<span class="small muted">'+r.type+' · '+escape(r.id)+'</span><h3>'+escape(r.title)+'</h3>'+button('Open record '+icon('ArrowUpRight'),'open-graph-record','quiet small')+'<div class="graph-links">'+linked.map(e=>{const other=data.records.find(n=>n.id===(e.source===id?e.target:e.source));return '<button data-graph-record="'+other.id+'"><span>'+escape(other.title)+'</span><small>'+e.relation+'</small></button>';}).join('')+'</div>';window.KnowledgeGraph.select(id);}
function graphList(query=''){const data=graphRecords();document.querySelector('#graph-records').innerHTML=data.records.filter(r=>r.title.toLowerCase().includes(query.toLowerCase())).map(r=>'<button data-graph-record="'+r.id+'">'+icon(r.type==='note'?'FileText':r.type==='project'?'BriefcaseBusiness':'BookOpen')+'<span>'+escape(r.title)+'</span></button>').join('')||'<p class="small muted">No matching records</p>';}
function render(){document.querySelectorAll('.folder-drawer').forEach(d=>d.remove());K.destroy();window.KnowledgeGraph.destroy();document.documentElement.dataset.theme=state.theme;studio();const routes={Home:home,Notes:()=>state.library?library():noteView(),Journal:()=>noteView(true),Tasks:taskBoard,Plan:plan,Work:work,Focus:focus,Habits:habits,Study:study,Goals:goals,Settings:prefs,Statistics:()=>report('Statistics'),History:()=>report('Habit history'),Recovery:()=>`<div class="main">${head('Recovery',routeButton('Habits','Habits','quiet'))}<div class="section-title"><span class="muted small">Recent dates</span></div>${['October 7','October 6'].map(date=>`<div class="task-row"><div class="content">Practise one problem<div class="small muted">${date}</div></div>${button('Freeze','freeze','border small')}</div>`).join('')}</div>`};document.querySelector('#app').innerHTML=`<div class="shell ${state.collapsed?'collapsed':''}" data-option="${state.option}">${sidebar()}${state.option==='C'?spacePanel():''}<div class="workspace">${topbar()}${state.option==='D'?tabs():''}${(routes[state.route]||home)()}</div>${state.graphOpen?graphPanel():''}</div>`;document.querySelector('#search-icon').innerHTML=icon('Search');if(state.route==='Journal'||state.route==='Notes'&&!state.library){const id=state.route==='Journal'?'journal':state.note;K.mount(document.querySelector('#editor'),state.edits[id]|| (id==='journal'?'<p>A new day, a little room to think.</p><h2>Today</h2><p>I want to make steady progress on the migration, leave clear notes for future me, and keep a little energy for learning.</p><h2>One thing to remember</h2><p>I can choose the care I put into the next small step.</p>':notes[id].content),json=>{state.edits[id]=json;if(notes[id])notes[id].markdown=K.markdown(json);persist();const saveStatus=document.querySelector('#save-status');if(saveStatus)saveStatus.textContent='Saved locally';const count=document.querySelector('#word-count');if(count)count.textContent=document.querySelector('.prose')?.innerText.trim().split(/\s+/).length+' words';});}if(state.graphOpen){const data=graphRecords();window.KnowledgeGraph.mount(document.querySelector('#record-graph'),data,graphDetails);document.querySelector('#graph-summary').textContent=data.records.length+' records · '+data.edges.length+' links';graphList();graphDetails(state.graphSelection);}persist();}
function navigate(route){if(route==='Notes')state.library=true;state.route=route;render();window.scrollTo(0,0);}
function openNote(id){if(notes[id]){state.note=id;state.library=false;state.route='Notes';render();window.scrollTo(0,0);}}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-node],a');if(!el)return;
if(el.dataset.option){state.option=el.dataset.option;render();return;}
if(el.dataset.route){navigate(el.dataset.route);return;}
if(el.dataset.note){openNote(el.dataset.note);return;}
if(el.getAttribute('href')?.startsWith('#note/')){e.preventDefault();openNote(el.getAttribute('href').slice(6));return;}
if(el.dataset.folder){state.folders[el.dataset.folder]=!state.folders[el.dataset.folder];const drawer=el.closest('.folder-drawer');if(drawer){drawer.querySelector('.folder-tree').outerHTML=tree();persist();}else render();return;}
if(el.dataset.libraryFolder){state.activeFolder=state.activeFolder===el.dataset.libraryFolder?'':el.dataset.libraryFolder;render();return;}
if(el.dataset.graphType){const type=el.dataset.graphType;state.graphTypes=state.graphTypes.includes(type)?state.graphTypes.filter(t=>t!==type):[...state.graphTypes,type];render();return;}
if(el.dataset.graphRecord){graphDetails(el.dataset.graphRecord);return;}
if(el.dataset.space){state.space=el.dataset.space;navigate('Home');return;}
if(el.dataset.node){state.selectedGraph=el.dataset.node;render();return;}
if(el.dataset.project){navigate('Work');toast(projects.find(p=>p.id===el.dataset.project)?.title||'Project');return;}
if(el.dataset.check){const task=state.tasks.find(t=>t.id===+el.dataset.check);task.status=task.status==='Done'?'Today':'Done';render();return;}
if(el.dataset.habit!==undefined){state.habits[+el.dataset.habit]=!state.habits[+el.dataset.habit];render();return;}
if(el.dataset.schedule){state.tasks.find(t=>t.id===+el.dataset.schedule).status='Today';render();return;}
if(el.dataset.preset){clearInterval(focusInterval);focusRunning=false;focusMinutes=+el.dataset.preset;focusSeconds=focusMinutes*60;render();return;}
if(el.dataset.pref){state.prefs[el.dataset.pref]=!state.prefs[el.dataset.pref];render();return;}
if(el.dataset.prefSection){document.getElementById(el.dataset.prefSection).scrollIntoView({behavior:'smooth',block:'start'});return;}
if(el.hasAttribute('data-close')){document.querySelector('#search').close();return;}
const action=el.dataset.action;if(!action)return;
if(action.startsWith('focus-')){focusTitle=state.tasks.find(t=>t.id===+action.slice(6)).title;navigate('Focus');return;}
switch(action){
case 'theme':state.theme=state.theme==='light'?'dark':'light';render();break;
case 'collapse':state.collapsed=!state.collapsed;render();break;
case 'search':openSearch();break;
case 'choose':state.choice=state.option;persist();studio();toast(`${state.option} · ${options[state.option][0]} selected`);break;
case 'wide':state.prefs.wide=!state.prefs.wide;render();break;
case 'serif':state.prefs.serif=!state.prefs.serif;render();break;
case 'cover':{const id=state.route==='Journal'?'journal':state.note;if(state.covers[id]){showMenu([{label:'Change cover',run:()=>pickCover(id)},{label:'Remove cover',run:()=>{delete state.covers[id];render();}}],el);}else pickCover(id);break;}
case 'page-menu':showMenu([{label:'New note',run:newNote},{label:'Wide pages',run:()=>{state.prefs.wide=!state.prefs.wide;render();}},{label:'Export note as Markdown',run:downloadNote},{label:'Arrange sidebar',run:arrangeSidebar},{label:'Settings',run:()=>navigate('Settings')}],el);break;
case 'new-note':newNote();break;
case 'all-notes':navigate('Notes');break;
case 'all-folders':state.activeFolder='';render();break;
case 'new-folder':newFolder();break;
case 'note-drawer':showFolderDrawer();break;
case 'arrange':arrangeSidebar();break;
case 'graph':state.graphOpen=!state.graphOpen;render();break;
case 'graph-expand':document.querySelector('.right-graph').classList.toggle('expanded');break;
case 'graph-in':window.KnowledgeGraph.zoom(1.25);break;
case 'graph-out':window.KnowledgeGraph.zoom(.8);break;
case 'graph-fit':window.KnowledgeGraph.fit();break;
case 'open-graph-record':{const record=graphRecords().records.find(r=>r.id===state.graphSelection);if(record?.noteId)openNote(record.noteId);else if(record)inspectRecord(record);break;}
case 'download-note':downloadNote();break;
case 'new-task':navigate('Tasks');document.querySelector('.inline-add input')?.focus();break;
case 'new-project':showEntry('Project name',value=>{projects.push({id:'project-'+Date.now(),title:value,status:'Planned',progress:0,next:'Choose next action',date:'—'});render();});break;
case 'timer':focusRunning=!focusRunning;clearInterval(focusInterval);if(focusRunning)focusInterval=setInterval(()=>{focusSeconds=Math.max(0,focusSeconds-1);const timer=document.querySelector('#timer');if(timer)timer.textContent=timerText();if(!focusSeconds){clearInterval(focusInterval);focusRunning=false;toast('Focus session complete');if(state.route==='Focus')render();}},1000);render();break;
case 'reset-timer':clearInterval(focusInterval);focusRunning=false;focusSeconds=focusMinutes*60;render();break;
case 'habits-history':navigate('History');break;
case 'habits-today':navigate('Habits');break;
case 'recovery':navigate('Recovery');break;
case 'freeze':el.textContent='Frozen';el.disabled=true;toast('Preview freeze applied');break;
case 'reflection':state.reflection=document.querySelector('#reflection').value;persist();toast('Preview reflection saved');break;
case 'export':{const blob=new Blob([JSON.stringify({option:state.choice||state.option,name:options[state.choice||state.option][0],theme:state.theme,prefs:state.prefs},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='tempo-design-choice.json';a.click();URL.revokeObjectURL(url);break;}
case 'reset':localStorage.removeItem(storeKey);location.assign('/');break;
case 'pomodoro':toast('Pomodoro selected');break;
case 'track':toast('Time tracking layout will keep the bottom dock');break;
default:toast('Layout preview · this action is available in Tempo');
}
});
function showEntry(label,save){const dialog=document.createElement('dialog');dialog.innerHTML=`<form style="padding:22px"><h2>${label}</h2><input aria-label="${label}" placeholder="${label}" required maxlength="100" style="width:100%;margin:16px 0"><div class="row" style="justify-content:flex-end"><button type="button" data-cancel>Cancel</button><button class="primary" type="submit">Create</button></div></form>`;document.body.append(dialog);dialog.querySelector('[data-cancel]').onclick=()=>{dialog.close();dialog.remove();};dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const value=dialog.querySelector('input').value.trim();if(!value)return;dialog.close();dialog.remove();save(value);};dialog.addEventListener('close',()=>dialog.remove());dialog.showModal();}
function newNote(){const dialog=document.createElement('dialog');const paths=[...new Set([...Object.values(notes).map(n=>n.path),...(saved.emptyFolders||[])])];dialog.innerHTML='<form class="entry-form"><h2>New note</h2><label>Title<input name="title" aria-label="Note title" placeholder="Untitled" required maxlength="100" autofocus></label><label>Folder<select name="folder" aria-label="Note folder">'+paths.map(p=>'<option '+(p===state.activeFolder?'selected':'')+'>'+escape(p)+'</option>').join('')+'</select></label><div class="row"><button type="button" data-cancel>Cancel</button><button class="primary" type="submit">Create note</button></div></form>';document.body.append(dialog);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.querySelector('form').onsubmit=e=>{e.preventDefault();const title=dialog.querySelector('[name=title]').value.trim();if(!title)return;const path=dialog.querySelector('[name=folder]').value;const id='note-'+Date.now();notes[id]={title,path,folder:path.split('/')[0],tag:'note',updated:'Just now',content:'<p></p>',markdown:'',links:[]};path.split('/').forEach((_,i,a)=>state.folders[a.slice(0,i+1).join('/')]=true);dialog.close();openNote(id);setTimeout(()=>document.querySelector('.prose')?.focus(),80);};dialog.showModal();}
function newFolder(){showEntry('Folder path',path=>{path=path.trim().split('/').filter(Boolean).join('/');if(!path)return;saved.emptyFolders=[...new Set([...(saved.emptyFolders||[]),path])];path.split('/').forEach((_,i,a)=>state.folders[a.slice(0,i+1).join('/')]=true);state.activeFolder=path;render();toast('Folder created');});}
function showFolderDrawer(){const dialog=document.createElement('dialog');dialog.className='folder-drawer';dialog.innerHTML='<div class="graph-head"><h2>Notes</h2><button data-cancel aria-label="Close folders">'+icon('X')+'</button></div>'+tree()+button(icon('Plus')+' New note','new-note','quiet');document.body.append(dialog);dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.addEventListener('click',e=>{if(e.target.closest('[data-note]'))dialog.close();});dialog.showModal();}
function arrangeSidebar(){const dialog=document.createElement('dialog');dialog.className='arrange-dialog';dialog.innerHTML='<div class="graph-head"><h2>Sidebar order</h2><button data-cancel aria-label="Close sidebar order">'+icon('X')+'</button></div><div id="order-list"></div>';document.body.append(dialog);function draw(){dialog.querySelector('#order-list').innerHTML=orderedNav().map(([name,image],i)=>'<div class="order-row" draggable="true" data-order="'+name+'">'+icon('GripVertical')+icon(image)+'<span>'+name+'</span><button data-up="'+name+'" aria-label="Move '+name+' up" '+(!i?'disabled':'')+'>'+icon('ArrowUp')+'</button><button data-down="'+name+'" aria-label="Move '+name+' down" '+(i===nav.length-1?'disabled':'')+'>'+icon('ArrowDown')+'</button></div>').join('');}function move(name,index){const order=orderedNav().map(([n])=>n);order.splice(order.indexOf(name),1);order.splice(index,0,name);state.navOrder=order;persist();draw();document.querySelector('.sidebar').outerHTML=sidebar();}dialog.onclick=e=>{const b=e.target.closest('[data-up],[data-down]');if(b){const name=b.dataset.up||b.dataset.down;const direction=b.dataset.up?-1:1;move(name,orderedNav().findIndex(([n])=>n===name)+direction);dialog.querySelector('[data-'+(direction<0?'up':'down')+'="'+name+'"]')?.focus();}};dialog.ondragstart=e=>{const row=e.target.closest('[data-order]');if(row)e.dataTransfer.setData('application/x-tempo-nav',row.dataset.order);};dialog.ondragover=e=>{if(e.target.closest('[data-order]'))e.preventDefault();};dialog.ondrop=e=>{const row=e.target.closest('[data-order]'),name=e.dataTransfer.getData('application/x-tempo-nav');if(row&&name){e.preventDefault();move(name,orderedNav().findIndex(([n])=>n===row.dataset.order));}};dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();draw();dialog.showModal();}
function downloadNote(){if(state.route!=='Notes'||state.library){toast('Open a note to export its Markdown');return;}const n=notes[state.note];const markdown=K.markdown(state.edits[state.note]||n.content);const text='---\nid: '+JSON.stringify(state.note)+'\ntitle: '+JSON.stringify(n.title)+'\nfolder: '+JSON.stringify(n.path)+'\ntags: ['+JSON.stringify(n.tag)+']\n---\n\n# '+n.title+'\n\n'+markdown+'\n';const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const dialog=document.createElement('dialog');dialog.className='markdown-export';dialog.innerHTML='<div class="graph-head"><h2>Markdown export</h2><button data-cancel aria-label="Close Markdown export">'+icon('X')+'</button></div><textarea readonly aria-label="Markdown content"></textarea><div class="export-footer"><a class="primary" download="'+escape(n.title.replace(/[<>:"/\|?*]/g,'-')+'.md')+'" href="'+url+'">'+icon('Download')+' Download .md</a></div>';document.body.append(dialog);dialog.querySelector('textarea').value=text;dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onclose=()=>{URL.revokeObjectURL(url);dialog.remove();};dialog.showModal();}
function showMenu(items,anchor){document.querySelector('#page-popover')?.remove();const menu=document.createElement('div');menu.id='page-popover';menu.className='slash-menu';menu.style.position='fixed';const rect=anchor.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(innerWidth-210,rect.right-200))+'px';menu.style.top=(rect.bottom+5)+'px';menu.style.bottom='auto';menu.setAttribute('role','menu');items.forEach(item=>{const b=document.createElement('button');b.setAttribute('role','menuitem');b.textContent=item.label;b.onclick=()=>{menu.remove();item.run();};menu.append(b);});document.body.append(menu);menu.querySelector('button').focus();setTimeout(()=>{document.addEventListener('click',function close(e){if(!menu.contains(e.target)){menu.remove();document.removeEventListener('click',close);}});});}
function pickCover(id){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp';input.onchange=()=>{const file=input.files[0];if(!file)return;if(file.size>2*1024*1024){toast('Choose an image under 2 MB for this preview.');return;}const reader=new FileReader();reader.onload=()=>{state.covers[id]=reader.result;render();};reader.readAsDataURL(file);};input.click();}
document.addEventListener('submit',e=>{const form=e.target.closest('[data-add-task]');if(!form)return;e.preventDefault();const input=form.querySelector('input');const title=input.value.trim();if(!title)return;state.tasks.push({id:Date.now(),title,project:state.space==='Work'?'Warehouse migration':'Personal',area:state.space,status:form.dataset.addTask,time:'',priority:'Normal'});render();});
document.addEventListener('input',e=>{if(e.target.id==='task-filter'){state.taskFilter=e.target.value;document.querySelector('#board').innerHTML=boardColumns();}if(e.target.id==='note-filter')document.querySelector('#note-list').innerHTML=tree(e.target.value);if(e.target.id==='library-filter'){document.querySelectorAll('.library-note').forEach(el=>{el.hidden=!el.textContent.toLowerCase().includes(e.target.value.toLowerCase());});}if(e.target.id==='graph-filter')graphList(e.target.value);if(e.target.id==='query')searchResults();});
document.addEventListener('change',e=>{if(e.target.dataset.move){state.tasks.find(t=>t.id===+e.target.dataset.move).status=e.target.value;render();}if(e.target.id==='theme-select'){state.theme=e.target.value;render();}});
document.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag]');if(card)e.dataTransfer.setData('text/plain',card.dataset.drag);});document.addEventListener('dragover',e=>{if(e.target.closest('[data-drop]'))e.preventDefault();});document.addEventListener('drop',e=>{const column=e.target.closest('[data-drop]');if(!column)return;e.preventDefault();const task=state.tasks.find(t=>t.id===+e.dataTransfer.getData('text/plain'));if(task){task.status=column.dataset.drop;render();}});
let searchIndex=0,searchMatches=[];
function openSearch(){const dialog=document.querySelector('#search');document.querySelector('#query').value='';searchIndex=0;searchResults();dialog.showModal();document.querySelector('#query').focus();}
function searchResults(){const query=document.querySelector('#query').value.toLowerCase();const all=[...Object.entries(notes).map(([id,n])=>({title:n.title,type:n.folder,icon:'FileText',open:()=>openNote(id)})),...projects.map(p=>({title:p.title,type:'Project',icon:'BriefcaseBusiness',open:()=>navigate('Work')})),...state.tasks.map(t=>({title:t.title,type:'Task',icon:'CircleCheck',open:()=>navigate('Tasks')})),...nav.map(([name,image])=>({title:name,type:'Page',icon:image,open:()=>navigate(name)}))];searchMatches=all.filter(item=>item.title.toLowerCase().includes(query));searchIndex=Math.min(searchIndex,Math.max(0,searchMatches.length-1));document.querySelector('#results').innerHTML=searchMatches.length?searchMatches.map((item,i)=>`<button class="result ${i===searchIndex?'selected':''}" data-result="${i}">${icon(item.icon)}${escape(item.title)}<span class="muted">${item.type}</span></button>`).join(''):'<div class="no-results">No results</div>';}
document.querySelector('#results').addEventListener('click',e=>{const el=e.target.closest('[data-result]');if(el){document.querySelector('#search').close();searchMatches[+el.dataset.result].open();}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}const dialog=document.querySelector('#search');if(dialog.open){if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();searchIndex=(searchIndex+(e.key==='ArrowDown'?1:-1)+Math.max(1,searchMatches.length))%Math.max(1,searchMatches.length);searchResults();document.querySelector('.result.selected')?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'&&searchMatches[searchIndex]){e.preventDefault();dialog.close();searchMatches[searchIndex].open();}}if(e.key==='Escape')document.querySelector('#page-popover')?.remove();if(e.key==='Enter'&&e.target.dataset.node){state.selectedGraph=e.target.dataset.node;render();}});
render();

